INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(16716, 'koKR', 'W imię Terokka!', 'W imię Terokka!', 0),
(16717, 'koKR', 'Chrońcie Zasłonę!', 'Chrońcie Zasłonę!', 0),
(16718, 'koKR', 'Mroczny Ogniu – pomścij nas!', 'Mroczny Ogniu – pomścij nas!', 0),
(16719, 'koKR', 'Ssssekk-sara Rith-nealaak!', 'Ssssekk-sara Rith-nealaak!', 0),
(16720, 'koKR', 'Arak-ha!', 'Arak-ha!', 0),
(17762, 'koKR', 'Ikiss nie – rak, rak – umrze...', '', 0),
(17763, 'koKR', 'Ty umrzeć – ka! Z dala od błyskotek!', '', 0),
(17764, 'koKR', 'Mmmmmm...', '', 0),
(17765, 'koKR', 'Mmm, ty walczyć z Ikissem? Aa-ak!', '', 0),
(17767, 'koKR', 'Ikiss pociąć cię, śliczności – ak-a-ak – posiekać, tak!', '', 0),
(17768, 'koKR', 'Ak-a-ra-k! Nie ma ucieczki dla – kra – ciebie!', '', 0),
(17769, 'koKR', 'Ra-ak! Błyskotki, tak. Śliczne błyskotki! Ak! Moc, wielka moc. Ra-kra! Moc w błyskotkach! Ak-kra!', '', 0),
